import { test, expect } from "@playwright/test";

test("a browser test", async ({ page }) => {
  await page.setContent("<h1>Library</h1>");
  await expect(page.getByRole("heading", { name: "Library" })).toBeVisible();
});

import { test, expect } from "@playwright/test";

test("find by role", async ({ page }) => {
  await page.setContent("<button>Borrow</button>");
  await expect(page.getByRole("button", { name: "Borrow" })).toBeVisible();
});

import { test, expect } from "@playwright/test";

test("labels identify inputs", async ({ page }) => {
  await page.setContent('<label for="title">Book title</label><input id="title">');
  await page.getByLabel("Book title").fill("Moon");
  await expect(page.getByLabel("Book title")).toHaveValue("Moon");
});

import { test, expect } from "@playwright/test";

test("click an action", async ({ page }) => {
  await page.setContent('<button onclick="this.textContent=\"Done\"">Save</button>');
  await page.getByRole("button", { name: "Save" }).click();
  await expect(page.getByRole("button", { name: "Done" })).toBeVisible();
});

import { test, expect } from "@playwright/test";

test("assertions wait for a result", async ({ page }) => {
  await page.setContent("<p>Ready</p>");
  await expect(page.getByText("Ready", { exact: true })).toBeVisible();
});

import { test, expect } from "@playwright/test";

test("count repeated items", async ({ page }) => {
  await page.setContent("<ul><li>Moon</li><li>Ocean</li></ul>");
  await expect(page.getByRole("listitem")).toHaveCount(2);
});

import { test, expect } from "@playwright/test";

test("check a checkbox", async ({ page }) => {
  await page.setContent('<label><input type="checkbox">Remember this book</label>');
  const box = page.getByLabel("Remember this book");
  await box.check();
  await expect(box).toBeChecked();
});

import { test, expect } from "@playwright/test";

test("select an option", async ({ page }) => {
  await page.setContent('<label>Size<select><option value="s">Small</option><option value="l">Large</option></select></label>');
  await page.getByLabel("Size").selectOption("l");
  await expect(page.getByLabel("Size")).toHaveValue("l");
});

import { test, expect } from "@playwright/test";

test("test keyboard access", async ({ page }) => {
  await page.setContent("<button>First</button><button>Second</button>");
  await page.getByRole("button", { name: "First" }).focus();
  await page.keyboard.press("Tab");
  await expect(page.getByRole("button", { name: "Second" })).toBeFocused();
});

import { test, expect } from "@playwright/test";

test("mock a page response", async ({ page }) => {
  await page.route("https://books.test/", route => route.fulfill({ contentType: "text/html", body: "<h1>Book list</h1>" }));
  await page.goto("https://books.test/");
  await expect(page.getByRole("heading", { name: "Book list" })).toBeVisible();
});

import { test, expect } from "@playwright/test";

test("isolate test state", async ({ page }) => {
  await page.setContent("<p>Fresh test</p>");
  await expect(page.getByText("Fresh test", { exact: true })).toBeVisible();
});

import { test, expect } from "@playwright/test";

test("capture useful evidence", async ({ page }) => {
  await page.setContent("<h1>Library</h1>");
  await expect(page.getByRole("heading")).toHaveText("Library");
  await page.screenshot({ path: "library.png", fullPage: true });
});
